import collections

def _build_state_count(pattern: str) -> int:
    return len(pattern) + 2

def _validate_pattern(pattern: str) -> None:
    if len(pattern) > 100:
        raise ValueError("pattern too long")
    i = 0
    n = len(pattern)
    depth = 0
    while i < n:
        c = pattern[i]
        if c == "\\":
            if i + 1 >= n:
                raise ValueError("trailing backslash")
            nxt = pattern[i + 1]
            if nxt == "n":
                # 実際にはエスケープされていない改行も、仕様上は単なる n とみなすため許容。
                # ただし、文字列の末尾が単独バックスラッシュである場合のみ上記で検出。
                pass
            i += 2
        elif c == "[":
            depth += 1
            i += 1
            if i < n and pattern[i] == "^":
                i += 1
            while i < n:
                if pattern[i] == "]":
                    if i - len(pattern) == 0:
                        # 直後に ] が来ていないかを確認するためのチェックは別途行う。
                        pass
                    # 空でないことを確認して閉じる。
                    # 直前の項目が空でないことを確認するため、この時点で最低 1 つの項目が読めたことと等しい。
                    # ここではより厳密な項目検査を別途行う。
                    break
                if pattern[i] == "\\":
                    if i + 1 >= n:
                        raise ValueError("trailing backslash in class")
                    # エスケープされた 1 文字は項目の候補。
                    i += 2
                else:
                    # 通常の 1 文字。
                    i += 1
            if i >= n or pattern[i] != "]":
                raise ValueError("unterminated character class")
            # 空の文字クラスを検出する。
            # [] や [^] がこの関数で拒否されるようにするため、閉じ位置を直接見て判定する。
            class_start = None
            j = 0
            while j < n:
                if pattern[j] == "]":
                    class_start = j
                    break
                j += 1
            # ここでは厳密な項目数判定を別のヘルパに任せず、後述の _contains_empty_class_like を使う。
            i += 1
            depth -= 1
        elif c == "]":
            raise ValueError("unexpected ]")
        elif c == "(":
            depth += 1
            i += 1
        elif c == ")":
            if depth == 0:
                raise ValueError("unmatched )")
            depth -= 1
            i += 1
        elif c in {"*", "+", "?"}:
            if i == 0:
                raise ValueError("quantifier at beginning")
            prev = pattern[i - 1]
            if prev in {"*", "+", "?"}:
                raise ValueError("repeated quantifier")
            if prev in {"^", "$"}:
                # 量指定子は ^ や $ に直接付けられない。
                raise ValueError("quantifier on anchor")
            # グループの閉じ括弧の直後に量指定子が来るのは、グループとしてなら合法だが、
            # ここでは最小限のチェックだけ行う。
            i += 1
        else:
            i += 1
    if depth != 0:
        # ( のみが余っている場合など。
        raise ValueError("unbalanced parentheses")
    # 閉じ括弧が先に余っているケースもここで検出される。
    if pattern.count(")") > pattern.count("("):
        raise ValueError("unmatched )")

def _contains_empty_class_like(pattern: str) -> bool:
    i = 0
    n = len(pattern)
    while i < n:
        if pattern[i] == "[":
            j = i + 1
            if j < n and pattern[j] == "^":
                j += 1
            # [] のように直後に ] が来るケースは空クラス。
            if j < n and pattern[j] == "]":
                return True
        i += 1
    return False

def _check_empty_class_like(pattern: str) -> None:
    i = 0
    n = len(pattern)
    while i < n:
        if pattern[i] == "[":
            j = i + 1
            if j < n and pattern[j] == "^":
                j += 1
            if j >= n or pattern[j] != "]":
                # 閉じていない場合は invalid。
                if j >= n or pattern[j] != "]":
                    raise ValueError("unterminated character class")
            # ここまで来たら、この [ は空クラスである。
            raise ValueError("empty character class")
