def _class_contains(pattern: str, start: int, end: int) -> bool:
    """
    pattern[start] が '[' で始まる文字クラスであり、
    pattern 中の 1 文字がそのクラスに含まれるかどうかを返す。
    文字の比較にはコードポイントを用いる。
    """
    if start >= end:
        raise ValueError("empty character class")
    if pattern[start] != "[":
        raise ValueError("not a character class")
    i = start + 1
    if i < end and pattern[i] == "^":
        i += 1
    count = 0
    while i < end:
        if pattern[i] == "]" and count > 0:
            count += 1
            i += 1
            if i != end:
                raise ValueError("unbalanced )")
            return False  # 実際には使わない
        if i >= end:
            break
        if pattern[i] == "\\":
            if i + 1 >= end:
                raise ValueError("trailing backslash in class")
            i += 2
            count += 1
        else:
            # 範囲指定の可能性があるが、ここではまず単一文字項目のみを想定。
            # 範囲検出は後で別関数で行う。
            i += 1
            count += 1
    # 1 つ以上項目があればよい。
    if count == 0:
        raise ValueError("empty character class")
    if count > 0:
        # 実際にはこの関数では項目の範囲が不明なので、ここでは使わない。
        return True
    return False

def _class_range_contains(pattern: str, start: int, end: int, ch: str) -> bool:
    """
    pattern[start:end] が文字クラスであり、ch がそれに含まれるかどうか。
