    i = start + 1
    neg = False
    if i < end and pattern[i] == "^":
        neg = True
        i += 1
    count = 0
    # 項目が 1 つ以上あるかを数える。
    # 空の [] / [^] は invalid にするため、この関数では count > 0 を確認する。
    pos = i
    has_item = False
    while pos < end:
        if pattern[pos] == "]":
            # 閉じ括弧は項目として数えない。
            if count > 0:
                return (not neg) if has_item else False
            # 直後に閉じ括弧が来ていないなら invalid にする。
            break
        if pattern[pos] == "\\":
            if pos + 1 >= end:
                raise ValueError("trailing backslash in class")
            has_item = True
            pos += 2
            count += 1
        elif pattern[pos] == "-" and count > 0:
            # 範囲は前項目が単一文字で、その直後に - が来て、さらに 1 文字以上が続く形。
            # ここでは簡易に、前がエスケープまたは通常 1 文字なら範囲を許容する。
            # 詳細は _class_contains を使うことで代替する。
            has_item = True
            pos += 1
            count += 1
        else:
            has_item = True
            pos += 1
            count += 1
    if not has_item:
        raise ValueError("empty character class")
    # 実際にはこの関数だけだと範囲判定が不正確なため、別途範囲ヘルパを使う。
    return True

def _class_contains_char(pattern: str, start: int, end: int, ch: str) -> bool:
    if start >= end:
        return False
    if pattern[start] != "[":
        return False
    i = start + 1
    neg = False
