        neg = True
        i += 1
    # 文字クラスが空でなく、その項目が 1 つ以上であることを確認する。
    if i >= end or pattern[i] == "]":
        raise ValueError("empty character class")
    # 項目は左から順に読む。
    # 1 文字項目または x-y の範囲項目のみを認める。
    while i < end:
        if pattern[i] == "]":
            break
        if pattern[i] == "\\":
            if i + 1 >= end:
                raise ValueError("trailing backslash in class")
            # 1 文字項目
            i += 2
        elif pattern[i] == "-" and i > start + 1:
            # 範囲項目の '-' だが、ここでの判定は簡略。
            i += 1
        else:
            # 1 文字項目。
            i += 1
    if i >= end or pattern[i] != "]":
        raise ValueError("unterminated character class")
    # 範囲の x > y 検出などのチェックは別途必要。
    return True

