def regex_search(pattern: str, text: str) -> bool:
    if pattern == "":
        return True
    if len(pattern) > 100:
        raise ValueError("pattern too long")
    if len(text) > 10000:
        raise ValueError("text too long")
    # まず、簡単な invalid 検出だけを行う。
    try:
        _validate_pattern(pattern)
    except ValueError:
        raise
    if _contains_empty_class_like(pattern):
        raise ValueError("empty character class")
    # 以下で本格的にシミュレーションする前に、パターン中の invalid 文字や
    # 不正な文字列パターン検出を済ませておく。
    # ここでは簡略化のため、通常の 1 文字マッチと文字クラス/アンカーの
    # 処理のみを想定する。
    #
    # 実装の都合上、パターンは長さ 100 以下で、かつ各文字が合法に処理できることを前提とする。
    # 文字クラスや anchors を含む複雑なケースは別途必要。
    #
    # ここでは、最も単純なケースとして、パターンが正規に解釈できるかを確認し、
