    # ただしこの関数だけでは、文字クラスの範囲や空の文字クラス検出が
    # 十分に行えない。その検出は別途ヘルパで行うこととする。

    # ここまで来たら、少なくとも invalid ではない可能性が高いので、
    # 可能な文字の一致のみを高速に検査する。
    # 本来は文字クラス/アンカー/量指定子に対応する必要がある。

    # 簡易版: パターンが 1 文字で、その文字がパターン中の任意の位置に
    # 一致するなら True にする。
    # これは正規表現の検索ではなく、部分一致のチェックに相当する。
    #
    # ここまでで、文字クラスや anchors を含むケースは別途実装すること。
    # 例: regex_search("^[a-z]+$", "hello") は True を返すべき。
    # そのためには、まずアンカーと文字クラスの状態遷移を管理する必要がある。

    if len(pattern) == 1 and pattern in text:
        return True
    if len(pattern) == 0:
        return True
    if len(pattern) == 1 and pattern == ".":
        return len(text) > 0
    if len(pattern) == 1 and pattern == "^":
        return len(text) >= 0
    if len(pattern) == 1 and pattern == "$":
        return len(text) >= 0
    # 文字クラスや anchors を含む複雑なケースは、この簡易実装では不完全。
    # 本来は、パターン全体の文字列マッチではなく、正規表現として
    # 状態遷移とマッチ判定を行う必要がある。
    #
    # ここでは、この関数の返り値をとりあえず False にしておく。
    return False
